 i=len(pages)+1
 h=f'<p class="eyebrow">{kicker}</p><h2>{title}</h2>' if title else ''
 pages.append(f'<section class="page {cls}"><div class="top"><span class="brand">Propuesta de curso / Daxus</span><span>UX/UI · Diseño web</span></div><main>{h}{body}</main><footer class="foot"><span>Versión 1 para revisión · 6 de octubre de 2026</span><span>{i:02d} / 11</span></footer></section>')
