 body=f'<p class="eyebrow">Programa detallado · Módulo {m["n"]} de 6</p><article class="module expanded-module"><div class="modulehead"><span class="num">{m["n"]:02d}</span><h2>{m["title"]}</h2><span class="duration">{m["minutes"]} min</span></div><p class="objective"><b>Objetivo:</b> {m["objective"]}</p>'+''.join(ls)+f'<div class="exercise"><p><b>Ejercicio del módulo:</b> {m["task"]}</p><p><b>Cómo comprobar el aprendizaje:</b> {m["check"]}</p><p class="practice-note">La práctica independiente es adicional al tiempo de clase.</p></div></article>'
